import os,re
R='/workspace/casa-de-leilao/docs/design/pranchas';O=R+'/assets/obras'
LOGO=R+'/logo/svg/L3-horizontal-paper.svg'
def ic(n,s=18):
    p={'zoom-in':'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35M11 8v6M8 11h6"/>','zoom-out':'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35M8 11h6"/>','rotate-ccw':'<path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>'}
    if n in p: b=p[n]
    else: b=re.sub(r'^.*?<svg[^>]*>|</svg>\s*$','',open(f'{R}/assets/icons/{n}.svg').read(),flags=re.S)
    return f'<svg width="{s}" height="{s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{b}</svg>'
OB={'45434':('Under the Wave off Kanagawa (A Grande Onda)','Katsushika Hokusai, ca. 1830–32','H. O. Havemeyer Collection, Bequest of Mrs. H. O. Havemeyer, 1929',600/403),
'10481':('Heart of the Andes','Frederic Edwin Church, 1859','Bequest of Margaret E. Dows, 1909',599/330),
'436105':('The Death of Socrates','Jacques Louis David, 1787','Catharine Lorillard Wolfe Collection, Wolfe Fund, 1931',599/399)}
def cred(i,c='#5E564B'): t,a,l,_=OB[i];return f'<div style="font-size:12px;color:{c}"><b style="font-family:Fraunces;font-size:15px;color:inherit">{t}</b><br>{a} · The Met, {l} · Domínio público (CC0)</div>'
CSS=f'''body{{margin:0;background:#D9D2C4;font-family:Inter;color:#1F1B16}}.b{{width:1440px;padding:40px}}h1{{font-family:Fraunces;font-weight:600;font-size:34px;margin:6px 0}}
.tag{{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;background:#FBF0DC;color:#6B5220;border:1px solid #E9CF9C;padding:3px 10px;border-radius:99px}}
.l{{font-size:12px;font-weight:600;margin:22px 0 8px}}.l b{{background:#1F1B16;color:#fff;padding:2px 6px;border-radius:4px;margin-right:6px}}
.frame{{width:1440px;height:860px;position:relative;overflow:hidden;background:#F6F3EC;box-shadow:0 2px 8px #0003}}
.hd{{background:#FFFDF8;height:64px;display:flex;align-items:center;padding:0 32px;font-size:14px;border-bottom:1px solid #E6DFD2}}.nav{{margin:0 auto;display:flex;gap:28px}}
.ov{{position:absolute;inset:0;background:rgba(31,27,22,.72)}}.dlg{{position:absolute;background:#FFFDF8;border-radius:14px;box-shadow:0 20px 50px #0006;overflow:hidden}}
.bt{{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:40px;min-width:40px;padding:0 12px;border-radius:8px;border:1px solid #E6DFD2;background:#FFFDF8;font:600 13px Inter;color:#1F1B16}}
.bt.p{{background:#6E1E2B;color:#F6F3EC;border-color:#6E1E2B}}.bt.g{{border-color:transparent;background:transparent}}.foc{{outline:2px solid #6E1E2B;outline-offset:2px}}
.m{{width:390px;height:780px;position:relative;overflow:hidden;background:#1F1B16;border-radius:22px;box-shadow:0 2px 8px #0003;color:#F6F3EC}}
.bar{{position:absolute;left:0;right:0;bottom:0;height:76px;background:rgba(31,27,22,.92);display:flex;align-items:center;gap:8px;padding:0 14px}}
.bar .bt{{height:44px;min-width:44px;background:transparent;color:#F6F3EC;border-color:#5E564B}}
.note{{background:#FFFDF8;border-radius:10px;padding:16px 20px;font-size:13px;line-height:1.55;box-shadow:0 1px 3px #0002}}.note h3{{font-family:Fraunces;margin:0 0 6px;font-size:17px}}
.sk{{background:linear-gradient(90deg,#E6DFD2,#F1ECE2,#E6DFD2)}}.chip{{position:absolute;background:#1F1B16;color:#F6F3EC;font:600 12px Inter;padding:4px 8px;border-radius:6px}}
code{{background:#F1ECE2;padding:1px 5px;border-radius:4px;font-size:12px}}'''
def img(i,style=''):return f'<img src="file://{O}/{i}.jpg" style="display:block;{style}">'
def bg(i,size,pos,style=''):return f'<div style="background:url(file://{O}/{i}.jpg) no-repeat;background-size:{size};background-position:{pos};{style}"></div>'
def page_bg():return f'<div class="hd"><img src="file://{LOGO}" style="height:30px"><div class="nav"><span>Leilões ▾</span><span>Como funciona</span><span>Suporte/FAQ</span></div><span>R$ 7.000,00 · Ana R.</span></div>'
def head(z,t,d):return f'<html><head><meta charset="utf-8"><style>{CSS}</style></head><body><div class="b"><span class="tag">Página do lote · Dialog de zoom · proposta · tokens inalterados · sem dependência nova</span><h1>{z} · {t}</h1><p style="max-width:1000px">{d}</p>'
def dhead(i,extra=''):return f'<div style="display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #E6DFD2">{cred(i)}<div style="margin-left:auto;display:flex;gap:6px">{extra}<span class="bt g" aria-label="Fechar">{ic("x")}</span></div></div>'
def mob(i,inner,label,top=''):
    return f'<div><div class="l">{label}</div><div class="m"><div style="position:absolute;top:0;left:0;right:0;padding:14px 16px;font-size:12px;opacity:.9">{top}</div>{inner}<div class="bar"><span class="bt" aria-label="Diminuir">{ic("zoom-out",20)}</span><span class="bt" aria-label="Ampliar">{ic("zoom-in",20)}</span><span class="bt" aria-label="Redefinir">{ic("rotate-ccw",20)}</span><span style="flex:1;text-align:center;font-size:13px">{label.split("·")[-1].strip()}</span><span class="bt" style="background:#F6F3EC;color:#1F1B16" aria-label="Fechar">{ic("x",20)}</span></div></div></div>'
def mobile_row(i):
    ar=OB[i][3];h=390/ar;t=f'<b style="font-family:Fraunces">{OB[i][0]}</b><br>{OB[i][1]} · The Met (CC0)'
    fit=f'<div style="position:absolute;top:{(704-h)/2:.0f}px;left:0">{img(i,f"width:390px")}</div>'
    zoom=bg(i,f'{390*2.5}px auto','45% 40%','position:absolute;inset:0 0 76px 0')+'<div class="chip" style="top:64px;right:14px">2,5×</div>'
    load=f'<div style="position:absolute;top:{(704-h)/2:.0f}px;left:0;width:390px;height:{h:.0f}px;overflow:hidden">{img(i,"width:390px;filter:blur(10px);transform:scale(1.05);opacity:.8")}</div><div class="chip" style="top:{(704-h)/2+h+12:.0f}px;left:150px">Carregando…</div>'
    err=f'<div style="position:absolute;top:240px;left:40px;right:40px;text-align:center">{ic("image-off",40)}<p style="font:600 16px Inter;margin:12px 0 4px">Não foi possível carregar a imagem em alta.</p><p style="font-size:13px;opacity:.8;margin:0 0 16px">Verifique sua conexão.</p><span class="bt p" style="height:44px">{ic("refresh-cw")} Tentar de novo</span></div>'
    return f'<div style="display:flex;gap:22px">'+mob(i,fit,'M.1 · 1× · ajustada',t)+mob(i,zoom,'M.2 · duplo toque / pinça · 2,5×',t)+mob(i,load,'M.3 · carregando',t)+'</div><div style="display:flex;gap:22px;align-items:flex-start">'+mob(i,err,'M.4 · erro',t)+f'''<div class="note" style="width:760px;margin-top:38px"><h3>Mobile 390 (igual para Z1–Z3)</h3>Dialog em tela cheia (fundo tinta). <b>Pinça</b> 1×–4×, <b>duplo toque</b> alterna 1× ↔ 2,5× centrado no ponto tocado; <b>arrastar</b> só quando ampliado (em 1× o gesto vertical para baixo fecha — opcional). Barra inferior fixa, botões de 44 px: −, +, redefinir, nível atual, <b>Fechar</b> (sempre visível, inclusive no erro). <code>touch-action:none</code> só na área da imagem; pointer events com 2 ponteiros para pinça. Limites: a imagem nunca sai do quadro (clamp do translate).</div></div>'''
def common():
    return '''<div style="display:flex;gap:22px;margin-top:22px"><div class="note" style="flex:1"><h3>Abrir / fechar e teclado</h3>Gatilho: a imagem do lote vira <code>&lt;button aria-label="Ampliar imagem: {título}"&gt;</code> com cursor <code>zoom-in</code> e ícone maximize-2 no canto (hover/foco). Dialog shadcn (Radix): foco preso, <b>Esc</b> fecha e devolve o foco ao botão da imagem; <b>+ / −</b> zoom, <b>0</b> redefine, <b>setas</b> movem 10% quando ampliado. <code>DialogTitle</code> = título da obra; <code>aria-describedby</code> = artista e crédito. Nível de zoom anunciado em <code>aria-live="polite"</code>.</div>
<div class="note" style="flex:1"><h3>Imagem, carregamento e erro</h3><code>next/image</code> com <code>sizes="(max-width:768px) 100vw, 80vw"</code>, <code>quality={90}</code>, <code>placeholder="blur"</code> com a miniatura da vitrine; a versão grande só carrega ao abrir. Carregando: miniatura desfocada + "Carregando…"; controles de zoom desativados. Erro: ícone image-off, mensagem e <b>Tentar de novo</b> (re-monta a imagem com <code>key</code>); Fechar continua ativo.</div>
<div class="note" style="flex:1"><h3>Movimento</h3>Transições de zoom 180 ms <code>ease-out</code> só em <code>transform</code>. <code>prefers-reduced-motion</code>: sem animação de zoom/pan (salta direto), Dialog só com fade 0–100 ms, lente/painel continuam funcionando. Nada de inércia no arrastar. Crédito da obra sempre visível no Dialog.</div></div></div></body></html>'''
# ---------- Z1
i='45434';W=1100;H=W/OB[i][3]
z1=head('Z1','Lupa circular que segue o mouse','Dialog grande (1200 px) com a obra inteira; ao passar o mouse aparece uma lente circular de 220 px com 2,5× (background-position calculado do ponteiro). Clique trava/destrava a lente; roda do mouse ajusta 2×–4×.')
lx,ly=640,300;D=220;Z=2.5
lens=bg(i,f'{W*Z}px auto',f'{-(lx*Z-D/2)}px {-(ly*Z-D/2)}px',f'position:absolute;left:{lx-D/2}px;top:{ly-D/2}px;width:{D}px;height:{D}px;border-radius:50%;border:3px solid #FFFDF8;box-shadow:0 0 0 1.5px #A9823A,0 10px 30px #0007')
z1+=f'''<div class="l"><b>Z1.1</b>Desktop 1440 · lente ativa (cursor oculto dentro da lente; fora dela cursor zoom-in)</div><div class="frame">{page_bg()}<div class="ov"></div><div class="dlg" style="left:120px;top:40px;width:1200px">{dhead(i,f'<span class="bt">{ic("search")} Lente 2,5×</span>')}<div style="padding:20px 50px;position:relative;background:#F1ECE2"><div style="position:relative;width:{W}px">{img(i,f"width:{W}px")}{lens}<div class="chip" style="left:{lx+D/2-30}px;top:{ly+D/2-10}px">2,5×</div></div></div><div style="padding:10px 18px;font-size:12px;color:#5E564B">Passe o mouse para ampliar · clique para fixar a lente · roda: 2×–4× · Esc fecha</div></div></div>'''
z1+=f'<div class="l"><b>Z1.2</b>Lente fixada por teclado (setas movem a lente, foco visível)</div><div style="display:flex;gap:22px"><div style="position:relative;width:560px;overflow:hidden;border-radius:10px" class="foc">{img(i,"width:560px")}'+bg(i,f'{560*3}px auto',f'{-(300*3-90)}px {-(150*3-90)}px','position:absolute;left:210px;top:60px;width:180px;height:180px;border-radius:50%;border:3px solid #FFFDF8;box-shadow:0 0 0 1.5px #A9823A')+'<div class="chip" style="left:12px;top:12px">3× · fixada</div></div><div class="note" style="flex:1"><h3>Regras Z1</h3>Lente: <code>pointermove</code> → <code>background-position</code> da mesma URL já carregada (sem 2ª requisição). Some quando o ponteiro sai da imagem. Em telas &lt; 1024 px ou sem hover (<code>@media (hover:none)</code>) a lente não existe: vale o modo mobile (pinça). Pró: leve, “de lupa de leiloeiro”. Contra: esconde parte do contexto; não serve para inspecionar bordas.</div></div>'
z1+=mobile_row(i)+common();open('Z1.html','w').write(z1)
# ---------- Z2
i='10481';W=760;H=W/OB[i][3];Z=2.5;rw,rh=W/Z,0;PW,PH=560,H
rx,ry=380,120;rw=PW/Z;rh=PH/Z
z2=head('Z2','Imagem + painel de zoom ao lado','Estilo e-commerce: obra à esquerda com retângulo-guia que segue o mouse; painel à direita mostra a área ampliada 2,5×. Ficha da obra no painel quando o mouse não está sobre a imagem.')
pan=bg(i,f'{W*Z}px auto',f'{-rx*Z}px {-ry*Z}px',f'width:{PW}px;height:{PH:.0f}px;border-radius:8px;border:1px solid #E6DFD2')
z2+=f'''<div class="l"><b>Z2.1</b>Desktop 1440 · mouse sobre a obra (guia + painel)</div><div class="frame">{page_bg()}<div class="ov"></div><div class="dlg" style="left:40px;top:60px;width:1360px">{dhead(i,f'<span class="bt">{ic("zoom-out")}</span><span class="bt" style="min-width:56px">2,5×</span><span class="bt">{ic("zoom-in")}</span>')}<div style="display:flex;gap:24px;padding:24px;background:#F1ECE2"><div style="position:relative;width:{W}px;cursor:crosshair">{img(i,f"width:{W}px")}<div style="position:absolute;left:{rx}px;top:{ry}px;width:{rw:.0f}px;height:{rh:.0f}px;border:2px solid #FFFDF8;outline:1.5px solid #A9823A;background:rgba(255,253,248,.18)"></div><div style="position:absolute;inset:0;box-shadow:inset 0 0 0 9999px rgba(31,27,22,.0)"></div></div><div>{pan}<div style="font-size:12px;color:#5E564B;margin-top:8px">Área ampliada 2,5× · roda do mouse ou +/− muda o nível</div></div></div></div></div>'''
z2+=f'<div class="l"><b>Z2.2</b>Estado inicial (sem hover): painel mostra a ficha · Z2.3 carregando</div><div style="display:flex;gap:22px"><div class="note" style="width:560px"><h3 style="font-size:22px">{OB[i][0]}</h3>{OB[i][1]}<br>Óleo sobre tela · 168 × 302,9 cm<br><span style="color:#5E564B">The Met, {OB[i][2]} · CC0</span><p style="margin-top:14px;color:#5E564B">{ic("search",14)} Passe o mouse sobre a obra para ampliar. Teclado: Tab até a obra, setas movem o guia, +/− zoom.</p></div><div style="position:relative;width:560px;height:{560/OB[i][3]:.0f}px;overflow:hidden;border-radius:8px">{img(i,"width:560px;filter:blur(10px);transform:scale(1.05)")}<div class="chip" style="left:12px;top:12px">Carregando imagem em alta…</div></div><div class="note" style="flex:1"><h3>Regras Z2</h3>Guia = tamanho do painel ÷ zoom, clamp nas bordas. Painel = <code>background-position</code>. Abaixo de 1024 px o painel some e vale o mobile. Pró: contexto + detalhe lado a lado, padrão conhecido. Contra: obras verticais deixam o painel estreito; precisa de 2 colunas.</div></div>'
z2+=mobile_row(i)+common();open('Z2.html','w').write(z2)
# ---------- Z3
i='436105';ar=OB[i][3];VW,VH=1300,640;Z=2
z3=head('Z3','Clique para ampliar + arrastar, com minimapa','Visualizador em tela quase cheia: 1º clique amplia 2× no ponto clicado, 2º clique 3×, 3º volta a 1× (cursor zoom-in → zoom-out). Arrastar move; barra com −/nível/+/redefinir e minimapa no canto com a área visível.')
IW=VH*ar
mm=f'<div style="position:absolute;right:20px;bottom:20px;width:180px;border:2px solid #FFFDF8;box-shadow:0 4px 14px #0006;border-radius:4px;overflow:hidden">{img(i,"width:180px")}<div style="position:absolute;left:{180*0.3:.0f}px;top:{(180/ar)*0.25:.0f}px;width:{180/Z*VW/IW if IW>VW else 180/Z:.0f}px;height:{(180/ar)/Z:.0f}px;border:2px solid #A9823A;background:rgba(255,253,248,.25)"></div></div>'
view=bg(i,f'{IW*Z:.0f}px auto',f'{-IW*Z*0.3:.0f}px {-VH*Z*0.25:.0f}px',f'width:{VW}px;height:{VH}px;cursor:grab')
z3+=f'''<div class="l"><b>Z3.1</b>Desktop 1440 · 2× arrastando (cursor grabbing) · minimapa</div><div class="frame">{page_bg()}<div class="ov"></div><div class="dlg" style="left:50px;top:24px;width:1340px;background:#1F1B16;color:#F6F3EC">{dhead(i).replace('#5E564B','#D9D2C4').replace('border-bottom:1px solid #E6DFD2','border-bottom:1px solid #3A332B')}<div style="position:relative;margin:0 20px">{view}{mm}<div class="chip" style="left:16px;top:16px">2× · arraste para mover</div></div><div style="display:flex;justify-content:center;gap:8px;padding:12px"><span class="bt">{ic("zoom-out")}</span><span class="bt" style="min-width:64px">200%</span><span class="bt foc">{ic("zoom-in")}</span><span class="bt">{ic("rotate-ccw")} Redefinir</span></div></div></div>'''
z3+=f'<div class="l"><b>Z3.2</b>1× ajustada (cursor zoom-in) · Z3.3 3× máximo (cursor zoom-out, + desativado)</div><div style="display:flex;gap:22px"><div style="position:relative;width:440px;background:#1F1B16;padding:20px;border-radius:10px">{img(i,"width:440px")}<div class="chip" style="left:30px;top:30px;background:#FFFDF8;color:#1F1B16">1× · clique para ampliar</div></div><div style="position:relative;background:#1F1B16;padding:20px;border-radius:10px">'+bg(i,f'{440*3}px auto','-560px -250px','width:440px;height:293px')+f'<div class="chip" style="left:30px;top:30px;background:#FFFDF8;color:#1F1B16">3× · clique volta a 1×</div></div><div class="note" style="flex:1"><h3>Regras Z3</h3>Níveis 1× → 2× → 3× (clique) e contínuo 1×–4× na roda/+/−. <code>transform: translate() scale()</code> numa <code>&lt;img&gt;</code> next/image com <code>will-change:transform</code>; clamp para não mostrar vazio. Minimapa: mesma miniatura, retângulo = viewport ÷ zoom; clicar no minimapa centraliza. Pró: melhor para inspecionar pinceladas e assinatura; mesmo modelo no desktop e mobile. Contra: mais estado para implementar.</div></div>'
z3+=mobile_row(i)+common();open('Z3.html','w').write(z3)
